private static EGLContext createEGLContext(EGLDisplay display, EGLConfig config, @SecureMode int secureMode) {
    int[] glAttributes;
    if (secureMode == SECURE_MODE_NONE) {
        glAttributes = new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION, 2, EGL14.EGL_NONE};
    } else {
        glAttributes = new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION, 2, EGL_PROTECTED_CONTENT_EXT, EGL14.EGL_TRUE, EGL14.EGL_NONE};
    }
    try {
        EGLContext context = EGL14.eglCreateContext(display, config, android.opengl.EGL14.EGL_NO_CONTEXT, glAttributes, 0);
        if (context == null) {
            throw new GlException("eglCreateContext failed");
        }
        return context;
    } catch (GlException e) {
        // 记录错误信息或采取恢复措施
        System.err.println("Failed to create EGL context: " + e.getMessage());
        // 可根据需要抛出更高层的异常或返回null
        return null;
    }
}
